const redis2 = $json.redis2 || [];

// Junta tudo em um array só
const allUrls = [...redis1, ...redis2];

// Mapeia cada url para o formato exigido pelo Airtable
const airtableAttachments = allUrls.map(url => ({ url }));

return [
  {
    json: {
      'Arquivos e mídia': airtableAttachments
    }
  }
];

// Pega os dados dos dois nodes de entrada
const redis1 = $items('memoria_redis1')[0].json.redis1 || [];
const redis2 = $items('Redis3')[0].json.redis2 || [];

// Junta as listas
const allUrls = [...redis1, ...redis2];

// Transforma as URLs no formato que o Airtable espera
const airtableAttachments = allUrls.map(url => ({ url }));

return [
  {
    json: {
      'Arquivos e mídia': airtableAttachments,
    }
  }
];

const arr1 = $json.redis1 || [];
const arr2 = $json.redis2 || [];

const sameValues = arr1.length === arr2.length &&
  arr1.every(item => arr2.includes(item));

return [{ json: { mesmaLista: sameValues } }];

// Lead já foi buscado por phone+tenant_id no node anterior (Search records1)
// Extrair o primeiro resultado do array retornado pelo GET Supabase
const lead = Array.isArray($('Search records1').item.json)
  ? $('Search records1').item.json[0]
  : $('Search records1').item.json;
return [{ json: lead }];

const input = $json || {};

const telefone = input.telefone || '';
const mensagem = String(input.mensagem || '');

let tipoMidia = 'texto';

if (mensagem === '[audio]') {
  tipoMidia = 'audio';
}

// contexto inicial do agente
let ctx = `
<estado_atual>
STATUS: start
Telefone: ${telefone}

[INFO_TECNICA: usuário enviou ${tipoMidia}]
</estado_atual>
`;

return [
{
json: {
...input,
_context: ctx,
_status_slug: 'new'
}
}
];

const lead = Array.isArray($json) ? $json[0] : $json;
const meta = lead.metadata || {};

// =============================
// HELPERS
// =============================

function text(value) {
  if (!value) return '';
  if (Array.isArray(value)) return value.join(', ');
  return String(value);
}

// =============================
// STATUS (Supabase já armazena como slug)
// =============================

const status = lead.status || 'new';

// =============================
// IDENTIDADE
// =============================

const nome = lead.name || 'Lead';
const recordId = lead.id || '';
const imovelRef = meta.imovel_ref || 'Não identificado';

// =============================
// MÍDIA
// =============================

const tipoMidia =
  lead?.message?.content_type ||
  lead?.content_type ||
  'texto';

// =============================
// BI DO LEAD (campos em metadata)
// =============================

const bairro = text(meta.bairro_interesse);
const budget = text(meta.faixa_valor);
const finalidade = text(meta.finalidade);
const origem = text(meta.origem);

let infoBI = '';

if (bairro) infoBI += `• Bairro: ${bairro}\n`;
if (budget) infoBI += `• Budget: ${budget}\n`;
if (finalidade) infoBI += `• Finalidade: ${finalidade}\n`;
if (origem) infoBI += `• Origem: ${origem}\n`;

// =============================
// ALERTAS DE URGÊNCIA
// =============================

const urgencyMap = {
  qualified: '🔥 FOCO TOTAL: Este lead tem alto score. Feche a visita.\n',
  proposal: '📅 LOGÍSTICA: Visita solicitada. Organize os horários.\n',
  new: '🆕 RECEPÇÃO: Lead novo. Identifique a dor e o desejo.\n'
};

const urgency = urgencyMap[status] || '';

// =============================
// BUILD CONTEXT
// =============================

let ctx = `\n<estado_atual>\n`;
ctx += `STATUS: ${status}\n`;

if (urgency) ctx += urgency;

ctx += `Cliente: ${nome}\n`;

if (imovelRef !== 'Não identificado') {
  ctx += `Imóvel de Interesse: ${imovelRef}\n`;
}

if (infoBI) {
  ctx += `\nDados já coletados:\n${infoBI}`;
}

if (recordId) {
  ctx += `record_id: ${recordId}\n`;
}

ctx += `\n[INFO_TECNICA: Mídia atual é ${tipoMidia}]\n`;
ctx += `</estado_atual>`;

// =============================
// OUTPUT
// =============================

return [{
  json: {
    ...lead,
    _context: ctx,
    _status_slug: status,
    nome_cliente: nome,
    record_id_guardiao: recordId,
    // Backward-compat aliases for Atendente node message template references
    Telefone: lead.phone,
    'Status Lead': lead.status,
    'Score do Lead': lead.score
  }
}];

const items = $input.all();
const output = [];

for (const item of items) {

const body = item.json.body || {};
const data = body.data || {};
const headers = item.json.headers || {};
const query = item.json.query || {};


// ===============================
// IGNORAR MENSAGENS DO BOT
// ===============================

if (data?.key?.fromMe === true) {
continue;
}


// ===============================
// TELEFONE / JID
// ===============================

let remoteJid = data?.key?.remoteJid || "";
let remoteJidAlt = data?.key?.remoteJidAlt || "";

let jid = null;

if (remoteJid.includes("@s.whatsapp.net")) {
jid = remoteJid;
}
else if (remoteJidAlt.includes("@s.whatsapp.net")) {
jid = remoteJidAlt;
}

let telefoneCompleto = null;
let telefoneDDI = null;
let telefoneLocal = null;
let sessionId = null;

if (jid) {

telefoneCompleto = jid.split("@")[0];

telefoneDDI = telefoneCompleto.substring(0,2);
const ddd = telefoneCompleto.substring(2,4);
let numero = telefoneCompleto.substring(4);

// correção automática Brasil
if (telefoneDDI === "55" && numero.length === 8) {
numero = "9" + numero;
}

telefoneLocal = ddd + numero;
telefoneCompleto = telefoneDDI + telefoneLocal;

sessionId = telefoneCompleto;

}


// ===============================
// NOME
// ===============================

const nome = data.pushName || "Cliente";


// ===============================
// MESSAGE TYPE
// ===============================

let messageType = "unknown";
let mensagem = null;

let audioUrl = null;
let audioSegundos = null;


// TEXTO SIMPLES
if (data.message?.conversation) {

messageType = "text";
mensagem = data.message.conversation;

}

// TEXTO EXTENDIDO
else if (data.message?.extendedTextMessage?.text) {

messageType = "text";
mensagem = data.message.extendedTextMessage.text;

}

// AUDIO
else if (data.message?.audioMessage) {

messageType = "audio";

audioUrl = data.message.audioMessage.url || null;
audioSegundos = data.message.audioMessage.seconds || null;

mensagem = "[audio]";

}

// IMAGEM
else if (data.message?.imageMessage) {

messageType = "image";
mensagem = "[image]";

}

// DOCUMENTO
else if (data.message?.documentMessage) {

messageType = "document";
mensagem = "[document]";

}


// ===============================
// TIMESTAMP
// ===============================

const timestamp = data.messageTimestamp || null;

let dataMensagem = null;

if (timestamp) {
dataMensagem = new Date(timestamp * 1000).toISOString();
}


// ===============================
// DETECTAR ORIGEM DO LEAD
// ===============================

let origemLead = "WhatsApp Site";

const utmSource = (query.utm_source || "").toLowerCase();

if (utmSource.includes("google")) {
origemLead = "Google Ads";
}

else if (
utmSource.includes("facebook") ||
utmSource.includes("meta")
) {
origemLead = "Meta Ads";
}

else if (utmSource.includes("instagram")) {
origemLead = "Instagram Orgânico";
}

else if (
utmSource.includes("zap") ||
utmSource.includes("vivareal") ||
utmSource.includes("olx")
) {
origemLead = "Portal Imobiliário";
}

else if (utmSource.includes("jp")) {
origemLead = "Anúncio JP";
}


// ===============================
// OUTPUT FINAL
// ===============================

output.push({

json: {

eventType: "WHATSAPP_MESSAGE",

instance: body.instance || null,

nome,

remoteJid: jid,

telefoneCompleto,
telefoneDDI,
telefoneLocal,

sessionId,

messageType,

mensagem,

audioUrl,
audioSegundos,

timestamp,
dataMensagem,

origemLead,

source: data.source || "whatsapp"

}

});

}

return output;

// UPSERT de leads retorna array com o lead criado/atualizado (Prefer: return=representation)
// Extrair o primeiro item para passar ao Dados do Lead
const lead = Array.isArray($json) ? $json[0] : $json;
return [{ json: lead }];

for (const item of $input.all()) {
  item.json.airtable_foto = [
    {
      "url": item.json.profilePictureUrl
    }
  ];
}

return $input.all();

